$already=is_file($configFile) || is_file(__DIR__.'/../storage/installed.lock');
if($already){ echo '<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><title>Installed</title><style>body{font-family:Arial;max-width:680px;margin:60px auto;padding:20px}a{display:inline-block;margin-top:15px}</style><h1>Installation already completed</h1><p>The installer is locked. Go to the login page.</p><a href="login.php">Open Login</a>'; exit; }
$error=null;$success=false;
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  $dbCfg=['host'=>trim((string)($_POST['db_host']??'localhost')),'port'=>(int)($_POST['db_port']??3306),'name'=>trim((string)($_POST['db_name']??'')),'user'=>trim((string)($_POST['db_user']??'')),'pass'=>(string)($_POST['db_pass']??''),'charset'=>'utf8mb4'];
  $base=rtrim(trim((string)($_POST['base_url']??'')),'/');
