  if($dbCfg['name']===''||$dbCfg['user']==='')throw new RuntimeException('Database name and username are required.');
  Installer::install($dbCfg,$base,trim((string)($_POST['google_client_id']??'')),trim((string)($_POST['google_client_secret']??'')),trim((string)($_POST['admin_email']??'')),(string)($_POST['admin_password']??''));
  $success=true;
 }catch(Throwable $e){$error=$e->getMessage();}
}
